const kinds={'organize-move':'Organizar archivo','organize-undo':'Deshacer organización','organize-error':'Organización detenida','recovery-start':'Revisar cierre inesperado','settings-recovery':'Recuperar ajustes','delete-local-folder':'Papelera de carpeta local','delete-remote-folder':'Papelera de carpeta en Proton','mkdir-local':'Crear carpeta local','mkdir-remote':'Crear carpeta en Proton','cloud-review':'Revisar cambios masivos','cloud-approve':'Autorizar cambios masivos','app-start':'Iniciar aplicación','scan-start':'Iniciar análisis','scan-complete':'Analizar duplicados','scan-cancelled':'Cancelar análisis','duplicate-trash':'Copia a la papelera','recovery':'Recuperación','disk-test':'Probar disco','manual-check':'Comprobación manual','restore-cloud':'Restaurar de Proton','upload':'Subir','download':'Descargar','move-local':'Mover en local','move-remote':'Mover en la nube','delete-local':'Papelera local','delete-remote':'Papelera de Proton','error':'Error','recuperación':'Recuperación','resolver conflicto':'Resolver conflicto','copia de seguridad':'Copia de seguridad'};
async function action(route,body){try{const r=await fetch('/'+route,{method:'POST',headers:{'X-Nube-Token':token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(r.status===403){location.reload();return}const data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo completar la petición');if(route==='resolve')notify('Resolución en curso. Puedes seguir el progreso en esta ventana.');await refresh();return true}catch(e){notify(e.message);return false}}
for(const id of ['sync','pause','login','retry'])q(id).onclick=()=>action(id==='retry'?'sync':id);
q('rebuild').onclick=()=>{if(confirm('Se volverán a comparar tus carpetas sin aplicar borrados anteriores. No se eliminarán tus documentos. ¿Reconstruir la sincronización?'))action('rebuild')};
for(const id of ['upload-limit','download-limit','metered','notifications','autostart','folder-setting','exclusions'])q(id).oninput=()=>{settingsDirty=true};
function fillSettings(p){q('upload-limit').value=p.uploadKiB;q('download-limit').value=p.downloadKiB;q('metered').checked=p.pauseMetered;q('notifications').checked=p.notifications;q('autostart').checked=p.autostart;q('folder-setting').value=p.localRoot;q('exclusions').value=p.exclusions.join('\\n');}
q('reset-settings').onclick=()=>{settingsDirty=false;if(lastPreferences)fillSettings(lastPreferences)};
q('save-settings').onclick=async()=>{const p={uploadKiB:Number(q('upload-limit').value),downloadKiB:Number(q('download-limit').value),pauseMetered:q('metered').checked,notifications:q('notifications').checked,autostart:q('autostart').checked,localRoot:q('folder-setting').value,exclusions:q('exclusions').value.split('\\n').map(p=>p.trim()).filter(Boolean)};if(lastPreferences&&p.localRoot!==lastPreferences.localRoot&&!confirm('¿Usar esta nueva carpeta? La anterior se conserva. Los archivos existentes en la nueva se combinarán con la nube.'))return;if(await action('settings',p)){settingsDirty=false;settingsSignature='';notify('Ajustes guardados.');await refresh()}};
let latestUpdate=null; q('updates-check').onclick=()=>action('updates/check',{});q('updates-auto').onchange=()=>action('updates/configure',{enabled:q('updates-auto').checked});q('updates-download').onclick=()=>{if(latestUpdate?.candidate&&confirm('¿Descargar '+latestUpdate.candidate.name+' ('+bytes(latestUpdate.candidate.size)+') desde GitHub?'))return action('updates/download',{id:latestUpdate.candidate.id});};q('updates-install').onclick=()=>{if(latestUpdate?.candidate)return action('updates/install',{id:latestUpdate.candidate.id});};q('updates-cancel').onclick=()=>action('updates/cancel',{});function updatesView(s){if(!s.updates)return;latestUpdate=s.updates;const u=s.updates,c=u.candidate,locked=!!s.busy||u.busy;q('tab-updates').textContent=c?'Actualizaciones · nueva':'Actualizaciones';q('updates-message').textContent=u.message;q('updates-checked').textContent=u.checkedAt?'Última consulta: '+date(u.checkedAt):'Todavía sin consultar.';q('updates-auto').checked=u.autoCheck;q('updates-auto').disabled=locked;q('updates-check').disabled=locked;q('updates-version').textContent=c?'Versión disponible: '+c.version+' · '+bytes(c.size):'';q('updates-notes').textContent=c?.notes||'';q('updates-notes').hidden=!c;q('updates-download').hidden=!c||u.ready;q('updates-download').disabled=locked;q('updates-install').hidden=!u.ready;q('updates-install').disabled=locked;q('updates-cancel').hidden=!u.busy;q('updates-cancel').disabled=!u.busy;q('updates-progress').hidden=u.phase!=='downloading';q('updates-progress').max=c?.size||1;q('updates-progress').value=u.bytes||0;q('updates-bytes').textContent=u.phase==='downloading'?bytes(u.bytes||0)+' / '+bytes(c?.size||0):'';}
q('folder-setting').onclick=()=>action('choose-folder');q('external-target').onclick=()=>action('external/choose');q('external-source').onclick=()=>action('external/choose-source');q('external-source-choose').onclick=()=>action('external/choose-source');q('external-source-all').onclick=()=>{q('external-source').value='';externalDirty=true;};q('choose-folder').onclick=()=>action('choose-folder');q('install-update').onclick=()=>action('update');q('rollback-update').onclick=()=>action('update/rollback');q('export-settings').onclick=()=>action('settings/export');q('import-settings').onclick=()=>action('settings/import');q('open-folder').onclick=()=>action('open-folder');
let safetyPlan=null,safetyPage=0;function renderSafety(){const p=safetyPlan;q('cloud-safety').hidden=!p;if(!p)return;const pages=Math.max(1,Math.ceil(p.actions.length/100));safetyPage=Math.min(safetyPage,pages-1);q('cloud-safety-reason').textContent=p.reason;q('cloud-safety-list').replaceChildren();for(const a of p.actions.slice(safetyPage*100,safetyPage*100+100)){const row=document.createElement('p');row.textContent=(kinds[a.type]||a.type)+' · '+a.path+(a.destination?' → '+a.destination:'');q('cloud-safety-list').appendChild(row);}q('cloud-safety-page').textContent=(safetyPage+1)+' / '+pages;q('cloud-safety-prev').disabled=safetyPage<=0;q('cloud-safety-next').disabled=safetyPage>=pages-1;}q('cloud-safety-prev').onclick=()=>{safetyPage--;renderSafety();};q('cloud-safety-next').onclick=()=>{safetyPage++;renderSafety();};q('cloud-safety-approve').onclick=()=>{if(safetyPlan&&confirm('¿Permitir la propagación de estos cambios masivos? Revisa los borrados y destinos antes de continuar.'))return action('cloud/approve',{id:safetyPlan.id});};function safetyState(s){if(safetyPlan?.id!==s.cloudSafety?.preview?.id)safetyPage=0;safetyPlan=s.cloudSafety?.preview||null;renderSafety();q('cloud-safety-approve').disabled=!!s.busy||!s.syncActive;const r=s.recovery||{};q('startup-recovery').textContent=(s.runHealth?.uncleanPrevious?'Se detectó un cierre inesperado. El índice y las operaciones se revalidan antes de continuar. ':'')+(r.interruptedOperations?'Se han revisado '+r.interruptedOperations+' operaciones interrumpidas.':'');}
let lastSettingsImportRevision=0;function preferences(s){if(!s.preferences)return;if(s.settingsImportRevision!==undefined&&s.settingsImportRevision!==lastSettingsImportRevision){lastSettingsImportRevision=s.settingsImportRevision;settingsDirty=false;settingsSignature='';orgSettingsLoaded=false;externalDirty=false;externalSignature='';}if(/^(Ajustes importados|Copia de ajustes|No se pudieron (importar|exportar))/.test(s.message||''))q('settings-transfer-status').textContent=s.message;const platform=s.system?.platform;q('platform-info').textContent=platform?platform.distribution+' · '+platform.architecture+' · '+platform.desktop+' / '+platform.session:'';q('platform-warning').textContent=platform?[...(platform.errors||[]),...(platform.warnings||[])].join(' · '):'';lastPreferences=s.preferences;q('update-status').textContent=s.updateResult?date(s.updateResult.time)+' · '+s.updateResult.message:'';const signature=JSON.stringify(s.preferences);if(!settingsDirty&&signature!==settingsSignature){fillSettings(s.preferences);settingsSignature=signature;}if(s.chosenFolder&&s.chosenFolder!==lastChosen){q('folder-setting').value=s.chosenFolder;settingsDirty=true;}lastChosen=s.chosenFolder;q('local-root').textContent=s.localRoot;q('network-status').textContent=s.system?.metered==='metered'?'Conexión de uso medido detectada.':s.system?.metered==='unmetered'?'Conexión sin límite de uso detectada.':'No se pudo determinar si la red es de uso medido; comprueba esa opción en los ajustes de red del escritorio.';}
